-- Semi-join: EXISTS (stops at first match)
SELECT * FROM employees e
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.emp_id = e.id);
-- Returns employees WITH orders (no duplication)

-- Anti-join: NOT EXISTS
SELECT * FROM employees e
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.emp_id = e.id);
-- Employees with NO orders

-- IN semi-join (optimized to semi-join in modern PG/MySQL)
SELECT * FROM employees WHERE emp_id IN (SELECT emp_id FROM orders);

-- NOT IN anti-join (NULL trap!)
SELECT * FROM employees WHERE emp_id NOT IN (SELECT emp_id FROM orders);
-- Watch for NULLs in subquery!

-- Planner chooses order based on stats/costs
-- Force order (PostgreSQL):
SET join_collapse_limit = 1;  -- disable reordering
-- Or use explicit parentheses:
SELECT * FROM a JOIN (b JOIN c ON b.id = c.id) ON a.id = b.id;

-- Join hints (PostgreSQL 12+ via pg_hint_plan extension)
/*+ Leading(a b c) */ SELECT * FROM a JOIN b ON ... JOIN c ON ...;

