-- Table with NULL in join column
CREATE TABLE test (id int, val int);
INSERT INTO test VALUES (1, 10), (2, NULL);

-- NOT IN with NULL subquery → ZERO rows
SELECT * FROM test WHERE id NOT IN (SELECT val FROM test);
-- Returns nothing! Because '1 NOT IN (10, NULL)' = UNKNOWN

-- NOT EXISTS works correctly
SELECT * FROM test t1 WHERE NOT EXISTS (SELECT 1 FROM test t2 WHERE t2.val = t1.id);
-- Returns id=1 (no match), id=2 (NULL ≠ 2)
